import{z as B,x as i,o as e,c as s,q as A,j as r,D as a,d as t,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"发展的微观证据","description":"","frontmatter":{"title":"发展的微观证据","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-development-micro.md","filePath":"econ/gd-development-micro.md","lastUpdated":1791413859000}'),d={name:"econ/gd-development-micro.md"};function m(p,E,D,c,h,_){const o=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=A('<h1 id="发展的微观证据" tabindex="-1">发展的微观证据 <a class="header-anchor" href="#发展的微观证据" aria-label="Permalink to &quot;发展的微观证据&quot;">​</a></h1><div class="epigraph"><p>增长理论写下按钮，现场证据告诉你按钮上落着多少只手；许多看起来显然的按钮，按下去什么都没发生。</p><footer>—— 据 Banerjee and Duflo, &quot;Growth Theory through the Lens of Development Economics&quot;, 2005；Poor Economics, 2011 整理</footer></div><p><a href="/econ/gd-structural-transformation">上一课</a>把份额迁移的引擎接进增长模型，总量路径有了部门结构。但「结构转型为什么慢」往下挖，会撞上微观：农户为什么不买每公顷回报为正的肥料，家庭为什么不为几块钱的健康防护掏钱。本课进入实证单元，读发展现场的第一手因果证据；试验方法本身已在 <a href="/econ/pe-rct-design-analysis">RCT 的设计与分析</a> 讲清，本课谈发展域的实质发现，以及微观证据与增长核算怎么接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏观与微观之间横着一道落差。发展核算把低收入国的落后拆给资本、人力与残差，大按钮在跨国账上常常不灵；而现场试验里微观回报高得惊人——肯尼亚肥料试验测得的边际回报可以到百分之几十。<span class="marginnote">「边际回报百分之几十」代入数字：花 100 元买肥料，一季多收 40 元的粮食，年化收益率远超任何银行存款。但前提是季初拿得出这 100 元，而且旱灾不会让收成归零——高回报自带这两个附加条款。</span>缺口因此有两面：回报为什么不被穷人抓取（行为、贴现、固定成本，还是外部性）；以及证据如何在现场被可信地拿到——把这些高回报当真并外推成增速，错在哪一步。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两枚锚点各钉一个设计要点。Miguel 与 Kremer 2004 的驱虫试验：蠕虫靠接触传染，服药的收益溢出到未服药的邻居，个人层面的效应估不出来，随机化必须按学校成簇、把溢出写进对照的定义——对照组并不干净，估计的是项目总效应。<span class="marginnote">「按学校成簇随机化」翻译成大白话：不是一枚硬币分一个孩子，而是整所学校整所地抽签。因为蠕虫靠接触传染，没吃药的孩子也被邻居的药保护着——只有整簇抽签比较，才能把这种「顺便的好处」算进总效应。</span>Duflo、Kremer 与 Robinson 2011 的肥料试验：回报高，但收益分散在整个生长季，季初一次性囤肥意味着与现金流和意志力对赌；把「种植时点的小额预订」提前一送，比农民学校便宜且抬升采用率。两条要点的分工：外部性决定随机化的层级，贴现与固定成本决定处理的形式——发展现场的设计不是把教科书方案搬下去，而是先测摩擦，再定处理。</p>',7)),(e(),r(l,null,{default:a(()=>[n(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIAL%5B%22%E7%8E%B0%E5%9C%BA%E9%9A%8F%E6%9C%BA%E5%8C%96%E8%AF%95%E9%AA%8C%22%5D%20--%3E%20LATE%5B%22%E5%B1%80%E9%83%A8%E5%B9%B3%E5%9D%87%E5%A4%84%E7%90%86%E6%95%88%E5%BA%94%22%5D%0A%20%20LATE%20--%3E%20GE%7B%22%E8%BF%87%E4%B8%89%E9%81%93%E9%97%A8%EF%BC%9A%E4%B8%80%E8%88%AC%E5%9D%87%E8%A1%A1%20%2F%20%E5%A4%96%E9%83%A8%E6%80%A7%E8%A7%84%E6%A8%A1%20%2F%20%E8%A1%8C%E6%94%BF%E8%83%BD%E5%8A%9B%22%7D%0A%20%20GE%20--%3E%7C%E8%BF%87%E4%B8%8D%E5%8E%BB%7C%20PAR%5B%22%E5%81%9C%E5%9C%A8%E7%AA%84%E5%8F%82%E6%95%B0%22%5D%0A%20%20GE%20--%3E%7C%E8%BF%87%E5%BE%97%E5%8E%BB%7C%20MACRO%5B%22%E8%BF%9B%E5%85%A5%E6%94%BF%E7%AD%96%E4%B8%8E%E5%A2%9E%E9%95%BF%E6%A0%B8%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微观回报与宏观增速之间是范畴差距，不是比例差距：试验测的是局部平均处理效应，把它乘上人口外推成 GDP 增速，要经过一般均衡、外部性规模与行政能力三道门（外推的判据见 <a href="/econ/pe-external-validity">外部有效性</a>，多项证据的合成见 <a href="/econ/pe-meta-analysis">Meta 分析</a>）。Banerjee 与 Duflo 把落差定位成「给定资源用好没有」：穷国缺的常常不是前沿技术，而是把既有技术与资源接通的安排——保险缺位让农民不买肥料，信贷配给让小生意停在无效率规模，这是 <a href="/econ/misallocation-tfp">错配</a> 的楔子在家庭层面的对应物；微观试验的作用是把楔子的位置与尺寸一个个量出来。证据于是按 <a href="/econ/pe-case-map">案例收束</a> 的口径组合：单个试验回答窄问题，窄参数进入结构模型或政策设计，才够得到增长。</p>',2)),(e(),r(l,null,{default:a(()=>[n(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%82%A5%E6%96%99%E5%9B%9E%E6%8A%A5%E4%B8%BA%E6%AD%A3%22%5D%20--%3E%20C1%7B%22%E5%AD%A3%E5%88%9D%E7%8E%B0%E9%87%91%E6%B5%81%E5%A4%9F%E5%9B%A4%E8%82%A5%3F%22%7D%0A%20%20C1%20--%3E%7C%E4%B8%8D%E5%A4%9F%7C%20W1%5B%22%E6%A5%94%E5%AD%90%3A%20%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%E4%B8%8E%E4%BF%A1%E8%B4%B7%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20C1%20--%3E%7C%E5%A4%9F%7C%20C2%7B%22%E6%94%B6%E7%9B%8A%E8%A6%81%E7%AD%89%E5%AD%A3%E6%9C%AB%E5%85%91%E7%8E%B0%22%7D%0A%20%20C2%20--%3E%20W2%5B%22%E6%A5%94%E5%AD%90%3A%20%E8%B4%B4%E7%8E%B0%E4%B8%8E%E6%84%8F%E5%BF%97%E5%8A%9B%22%5D%0A%20%20F%20--%3E%20C3%7B%22%E9%A3%8E%E9%99%A9%E8%B0%81%E6%8B%85%3F%20%E4%BF%9D%E9%99%A9%E7%BC%BA%E4%BD%8D%22%7D%0A%20%20C3%20--%3E%20W3%5B%22%E6%A5%94%E5%AD%90%3A%20%E4%B8%8B%E8%A1%8C%E9%A3%8E%E9%99%A9%E8%87%AA%E7%95%99%22%5D%0A%20%20W1%20--%3E%20FIX%5B%22%E5%A4%84%E7%90%86%3A%20%E5%B0%8F%E9%A2%9D%E9%A2%84%E8%AE%A2%20%2B%20%E6%8F%90%E5%89%8D%E4%B8%80%E9%80%81%22%5D%0A%20%20W2%20--%3E%20FIX%0A%20%20W3%20--%3E%20FIX2%5B%22%E5%A4%84%E7%90%86%3A%20%E9%85%8D%E5%A5%97%E4%BF%9D%E9%99%A9%E6%88%96%E6%88%90%E7%B0%87%E7%BB%99%E8%8D%AF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">初学者容易把「不买高回报肥料」读成穷人不理性。把时间轴拉长看：收益在季末才到，旱灾可能让它归零，季初的 100 元可能要挪去买口粮——先解决现金流与保险，「理性」才有用武之地。试验的价值正是分清楔子是钱的事还是心的事。</span></p><p><span class="marginnote">驱虫试验的后续争论是范例：单试验的效度、再分析与多年随访、成本收益的重算各有结论——「驱动全部基础教育」与「低成本健康干预」是两个命题，读文献要把它们分开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>随机化试验的问题窄，结构转型的变量慢：没有一个驱虫级的干预能顶替农业到工业的迁移，微观证据能给政策的方向与参数，给不了增速的答案。试验地与推广地在市场密度、行政能力上的差距把外部效度压窄；对照村的溢出把效应压低的方向也真实存在。伦理与分层是硬约束：谁先进对照组，不是统计问题。最后，把「微观回报高」读成「穷人不理性」同样错——肥料回报在雨天与干旱年不同，保险与现金流约束解释了大部分「不抓取」，行为只是余项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发展微观证据的两大设计要点：外部性决定随机化层级，贴现与固定成本决定处理形式。</li><li>驱虫与肥料试验分别钉住溢出与季初摩擦；摩擦先测，处理后定。</li><li>微观到宏观要过一般均衡、外部性、行政能力三道门，外推不是乘法。</li><li>家庭楔子是错配的微观对应物，试验的价值在量出楔子的位置与尺寸。</li><li>微观证据给参数与方向，不替代增长核算与结构转型。</li><li>出处：Miguel and Kremer, <em>Econometrica</em> 2004；Duflo, Kremer and Robinson, <em>AER</em> 2011；Banerjee and Duflo 2005/2011。</li></ul>',6))])}const u=B(d,[["render",m]]);export{f as __pageData,u as default};
